from Crypto.Util.number import *
from gmpy2 import isqrt
from secret import flag

p = getPrime(512)
q = getPrime(512)
n = p * q
phi = (p** 4 - 1) * (q**4 - 1)
l = isqrt((2*n**4 - 49 * n**2 + 2)//(4*n + 170*n**2)).bit_length()
d = getPrime(l)
e = inverse(d, phi)

m = bytes_to_long(flag)
c = pow(m,e,n)

print(f"n = {n}")
print(f"e = {e}")
print(f"c = {c}")

